PACKAGE_FILE="$WORKSPACE/hello-world-extension-${PKG_VERSION}.vsix"
if [ -x ./node_modules/.bin/vsce ]; then ./node_modules/.bin/vsce package -o "$PACKAGE_FILE" >"$TMPLOG" 2>&1 || { echo "ERROR: vsce packaging failed, printing tail of log:" >&2; tail -n 200 "$TMPLOG" >&2; exit 6; }
else npx --yes vsce package -o "$PACKAGE_FILE" >"$TMPLOG" 2>&1 || { echo "ERROR: npx vsce packaging failed, printing tail of log:" >&2; tail -n 200 "$TMPLOG" >&2; exit 7; }; fi
# Prepare integration harness
mkdir -p .vscode-test/runner
cat > .vscode-test/index.js <<'JS'
const path = require('path');const { runTests } = require('@vscode/test-electron');
async function main(){try{const extensionDevelopmentPath=path.resolve(process.cwd());const extensionTestsPath=path.resolve(process.cwd(),'.vscode-test','runner');await runTests({extensionDevelopmentPath,extensionTestsPath});console.log('INTEGRATION_TESTS_PASSED');process.exit(0);}catch(err){console.error(err);process.exit(8);}}
main();
JS
cat > .vscode-test/runner/index.js <<'JS'
const assert=require('assert');const fs=require('fs');const path=require('path');
module.exports = function () {
  describe('extension activation', function () {
    it('activation marker exists (with retries)', function (done) {
      this.timeout(300000);
      const marker = path.join(__dirname, '..', '..', 'out', 'activated.txt');
      const max=30;let tries=0;const iv=setInterval(()=>{tries++;if(fs.existsSync(marker)){clearInterval(iv);return done();}if(tries>=max){clearInterval(iv);return done(new Error('activation marker not found: '+marker));}},1000);
    });
  });
};
JS
# Run integration tests (runTests will download VS Code test host if needed)
# Capture run output; on failure print last 200 lines for debugging
TEST_LOG=$(mktemp -p /tmp vscode_test_log.XXXXXX)
trap 'rc=$?; tail -n 200 "$TEST_LOG" 2>/dev/null || true; rm -f "$TEST_LOG" || true; exit $rc' ERR
node .vscode-test/index.js >"$TEST_LOG" 2>&1 || { echo "ERROR: integration tests failed, tailing log:" >&2; tail -n 200 "$TEST_LOG" >&2; exit 8; }
# Evidence
./node_modules/.bin/tsc --version || true
ls -la node_modules/.bin || true
ls -lh "$PACKAGE_FILE" || true
ls -la out || true
echo "VALIDATION_COMPLETE"
exit 0

